def transform(grid):
    h,w=len(grid),len(grid[0])
    splits=[]
    for r in range(h):
        if len(set(grid[r]))==1 and r>0 and h-r-1>0 and r==h-r-1:
            splits.append(('h',r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)})==1 and c>0 and w-c-1>0 and c==w-c-1:
            splits.append(('v',c))
    if len(splits)!=1:
        raise ValueError(f'expected one equal-panel separator, found {splits}')
    orient,k=splits[0]
    if orient=='h':
        a=grid[:k]; b=grid[k+1:]
    else:
        a=[row[:k] for row in grid]; b=[row[k+1:] for row in grid]
    common=set(v for row in a for v in row)&set(v for row in b for v in row)
    if not common: raise ValueError('no shared panel color')
    # Shared color with the largest aligned overlap is the common background.
    color=max(common,key=lambda v:sum(a[r][c]==v and b[r][c]==v for r in range(len(a)) for c in range(len(a[0]))))
    return [[3 if a[r][c]==color and b[r][c]==color else color for c in range(len(a[0]))] for r in range(len(a))]
for i,(a,o) in enumerate(pairs,1):
    x=transform(a)
    print(i,x==o, sum(v for row in x for v in row),sum(v for row in o for v in row))

